  const levels = parsePalazzoLevels(record.levels);
  if (!levels) return null;
  const live = record.live as Record<string, unknown> | undefined;
  if (
    live !== undefined &&
    (!live || typeof live !== 'object' || typeof live.onAir !== 'boolean')
  )
    return null;
  const liquidsoap = record.liquidsoap as Record<string, unknown> | undefined;
  const icecast = record.icecast as Record<string, unknown> | undefined;
  if (
    !liquidsoap ||
    typeof liquidsoap.running !== 'boolean' ||
    typeof liquidsoap.connected !== 'boolean' ||
    (liquidsoap.staleSince !== null &&
      typeof liquidsoap.staleSince !== 'string') ||
    (liquidsoap.lastSampleAt !== null &&
      typeof liquidsoap.lastSampleAt !== 'string') ||
    !icecast ||
    typeof icecast.connected !== 'boolean'
  )
    return null;
  if (!isNonNegativeFinite(record.positionSeconds)) return null;
  if (
    record.remainingSeconds !== null &&
    !isNonNegativeFinite(record.remainingSeconds)
  )
    return null;
  return {
    schemaVersion: 1,
    instanceId: record.instanceId,
    bootId: record.bootId,
    sequence: record.sequence as number,
    availability,
    status,
    liquidsoap: {
      running: liquidsoap.running,
      connected: liquidsoap.connected,
      staleSince: liquidsoap.staleSince,
      lastSampleAt: liquidsoap.lastSampleAt,
    },
    icecast: { connected: icecast.connected },
    track,
    intro,
    positionSeconds: record.positionSeconds as number,
    remainingSeconds: record.remainingSeconds as number | null,
    levels,
    ...(live ? { live: { onAir: live.onAir as boolean } } : {}),
    ...(record.capabilities !== undefined
      ? { capabilities: parseCapabilities(record.capabilities) }
      : {}),
  };
}

/** Bounded capability names; anything malformed reads as no capability. */
function parseCapabilities(value: unknown): string[] {
  if (!Array.isArray(value) || value.length > 32) return [];
  return value.every((entry) => boundedString(entry, 64))
    ? [...(value as string[])]
    : [];
}

function parsePalazzoTrack(value: unknown): PalazzoTrackState | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Record<string, unknown>;
  if (!boundedString(record.playbackRequestId, 200)) return null;
  if (typeof record.url !== 'string' || !record.url) return null;
  if (
    typeof record.startedAt !== 'string' ||
    !Number.isFinite(Date.parse(record.startedAt))
  )
    return null;
  return {
    playbackRequestId: record.playbackRequestId,
    title: stringOrNull(record.title),
    artist: stringOrNull(record.artist),
    coverUrl: stringOrNull(record.coverUrl),
    url: record.url,
    startedAt: record.startedAt,
  };
}

function parsePalazzoIntro(
  value: unknown,
): PalazzoIntroState | 'malformed' | 'unknown-status' {
  if (!value || typeof value !== 'object') return 'malformed';
  const record = value as Record<string, unknown>;
  if (
    !boundedString(record.playbackId, 200) ||
    !boundedString(record.parentPlaybackId, 200) ||
    !boundedString(record.programId, 128) ||
    !boundedString(record.playbackRequestId, 200) ||
    typeof record.url !== 'string' ||
    typeof record.startedAt !== 'string' ||
    !Number.isFinite(Date.parse(record.startedAt)) ||
    !boundedString(record.status, 64) ||
    (record.failureReason !== undefined &&
      typeof record.failureReason !== 'string')
  )
    return 'malformed';
  if (record.status !== 'playing' && record.status !== 'failed')
    return 'unknown-status';
  return record as unknown as PalazzoIntroState;
}

function parsePalazzoLevels(value: unknown): PalazzoLevels | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Record<string, unknown>;
  const song = parseLevel(record.song);
  const instant = parseLevel(record.instant);
  const output = parseLevel(record.output);
  const intro =
    record.intro === undefined ? undefined : parseLevel(record.intro);
  if (!song || !instant || !output || (record.intro !== undefined && !intro))
    return null;
  return { song, instant, output, ...(intro ? { intro } : {}) };
}

function parseLevel(value: unknown): PalazzoAudioLevel | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Record<string, unknown>;
  if (!isFiniteNumber(record.rms) || !isFiniteNumber(record.peak)) return null;
  return { rms: record.rms as number, peak: record.peak as number };
}

export function parsePalazzoMixerState(
  value: unknown,
): PalazzoMixerState | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Record<string, unknown>;
  if (
    !isFiniteNumber(record.mainVolume) ||
    !isFiniteNumber(record.songVolume) ||
    !isFiniteNumber(record.instantVolume) ||
    typeof record.songMuted !== 'boolean' ||
    typeof record.instantMuted !== 'boolean'
  )
    return null;
  return record as unknown as PalazzoMixerState;
}

const EVENT_TYPES: ReadonlySet<string> = new Set<PalazzoPlaybackEventType>([
  'snapshot',
  'telemetry.connected',
  'telemetry.disconnected',
  'track.started',
  'track.ended',
  'intro.started',
  'intro.ended',
  'intro.failed',
  'playout.queued',
  'preflight.ready',
  'preflight.failed',
  'playout.started',
  'playout.transitioned',
  'playout.stopped',
  'playout.skipped',
  'playout.fallback',
  'playout.request_failed',
  'playout.next_queued',
  'playout.next_withdrawn',
  'instant.started',
  'instant.ended',
  'playback.position',
  'audio.levels',
  'heartbeat',
  'replay.gap',
]);

/** The correlation fields every Palazzo event carries, whatever its type. */
export interface PalazzoEventEnvelope {
  id: string;
  instanceId: string;
  bootId: string;
  sequence: number;
  occurredAt: string;
}

/**
 * What one SSE frame is (gaulatti/ariston#217). The client skips, rather than
 * drops the stream for:
 * - `unknown-type`: a well-formed frame of a type Alcantara does not know; its
 *   envelope still advances the sequence cursor;
 * - `unsupported-version`: a frame whose integer `schemaVersion` (the major
 *   version) is not 1. Nothing else of it is read, because another major may
 *   change what every field means.
 * Anything else that fails the contract is `malformed`.
 */
export type PalazzoFrame =
  | { kind: 'event'; event: PalazzoPlaybackEvent }
  | { kind: 'unknown-type'; envelope: PalazzoEventEnvelope }
  | { kind: 'unsupported-version' }
  | { kind: 'malformed' };

/** Parses a known Palazzo event, or null for anything else. */
export function parsePalazzoEvent(
  value: unknown,
  onUnknown?: PalazzoUnknownSink,
): PalazzoPlaybackEvent | null {
  const frame = classifyPalazzoFrame(value, onUnknown);
  return frame.kind === 'event' ? frame.event : null;
}

export function classifyPalazzoFrame(
  value: unknown,
  onUnknown?: PalazzoUnknownSink,
): PalazzoFrame {
  const malformed: PalazzoFrame = { kind: 'malformed' };
  if (!value || typeof value !== 'object') return malformed;
  const record = value as Record<string, unknown>;
  if (record.schemaVersion !== 1) {
    return Number.isSafeInteger(record.schemaVersion)
      ? { kind: 'unsupported-version' }
      : malformed;
  }
  if (
    !boundedString(record.id, 300) ||
    !boundedString(record.instanceId, 200) ||
    !boundedString(record.bootId, 200) ||
    !Number.isSafeInteger(record.sequence) ||
    (record.sequence as number) < 0 ||
    !boundedString(record.type, 200) ||
    typeof record.occurredAt !== 'string' ||
    !Number.isFinite(Date.parse(record.occurredAt)) ||
    !record.data ||
    typeof record.data !== 'object' ||
    Array.isArray(record.data)
  )
    return malformed;
  if (!EVENT_TYPES.has(record.type)) {
    return {
      kind: 'unknown-type',
      envelope: {
        id: record.id,
        instanceId: record.instanceId,
        bootId: record.bootId,
        sequence: record.sequence as number,
        occurredAt: record.occurredAt,
      },
    };
  }
  const type = record.type as PalazzoPlaybackEventType;
  const data = record.data as Record<string, unknown>;
  if (
    (type === 'track.started' ||
      type === 'track.ended' ||
      type === 'playout.request_failed') &&
    !boundedString(data.playbackRequestId, 200)
  )
    return malformed;
  if (
    (type === 'playout.next_queued' ||
      type === 'playout.next_withdrawn' ||
      type === 'instant.started' ||
      type === 'instant.ended') &&
    !boundedString(data.playbackId, 200)
  )
    return malformed;
  if (type === 'playout.next_withdrawn') {
    if (!boundedString(data.reason, 64)) return malformed;
    if (!NEXT_WITHDRAWN_REASONS.has(data.reason)) {
      onUnknown?.('withdrawn-reason');
      data.reason = 'other';
    }
  }
  if (
    (type === 'intro.started' ||
      type === 'intro.ended' ||
      type === 'intro.failed') &&
    (!boundedString(data.programId, 128) ||
      !boundedString(data.playbackId, 200) ||
      !boundedString(data.parentPlaybackId, 200))
  )
    return malformed;
  return { kind: 'event', event: record as unknown as PalazzoPlaybackEvent };
}

function stringOrNull(value: unknown): string | null {
  return typeof value === 'string' && value ? value : null;
}

function boundedString(value: unknown, max: number): value is string {
  return typeof value === 'string' && value.length > 0 && value.length <= max;
}

function isFiniteNumber(value: unknown): boolean {
  return typeof value === 'number' && Number.isFinite(value);
}

function isNonNegativeFinite(value: unknown): boolean {
  return isFiniteNumber(value) && (value as number) >= 0;
}

import { PalazzoProgramClient } from './palazzo-program.client';
import { PalazzoMachineClient } from './palazzo-machine.client';
import { RadioMetricsService } from './radio-metrics.service';
import type { ConfigService } from '@nestjs/config';
import type { PalazzoPlaybackState } from './palazzo-contract';
import { Logger } from '@nestjs/common';

/** The private cursor state these tests read directly. */
interface ClientInternals {
  currentBootId: string | null;
  lastSequence: number;
}

// gaulatti/alcantara#240: Palazzo's replay.gap event (palazzo#56) is a known
// type. It is counted under the existing gap counter and logged; it does not
// move the cursor, fetch anything or reach the engine.

const PROGRAM = 'radio-1';

function envelope(
  sequence: number,
  type: string,
  data: unknown = {},
  bootId = 'boot-1',
) {
  return {
    schemaVersion: 1,
    id: `${bootId}:${sequence}`,
    instanceId: 'palazzo-a',
    bootId,
    sequence,
    type,
    occurredAt: new Date().toISOString(),
    data,
  };
}

function idleState(sequence: number): PalazzoPlaybackState {
  return {
    schemaVersion: 1,
    instanceId: 'palazzo-a',
    bootId: 'boot-1',
    sequence,
    availability: 'available',
    status: 'idle',
    liquidsoap: {
      running: true,
      connected: true,
      staleSince: null,
      lastSampleAt: new Date().toISOString(),
    },
    icecast: { connected: true },
    track: null,
    intro: null,
    positionSeconds: 0,
    remainingSeconds: null,
    levels: {
      song: { rms: 0, peak: 0 },
      instant: { rms: 0, peak: 0 },
      output: { rms: 0, peak: 0 },
    },
  };
}

function frame(value: { id: string; type: string }): string {
  return `id: ${value.id}\nevent: ${value.type}\ndata: ${JSON.stringify(value)}\n\n`;
}

function sseResponse(frames: string[]): Response {
  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      for (const text of frames) controller.enqueue(encoder.encode(text));
      // Left open: the client stays connected.
    },
  });
  return new Response(stream, {
    status: 200,
    headers: { 'Content-Type': 'text/event-stream' },
  });
}

function createClient(fetchImpl: jest.Mock) {
  const metrics = new RadioMetricsService();
  const callbacks = {
    onSnapshot: jest.fn(),
    onEvent: jest.fn(),
    onStatus: jest.fn(),
    validateInstance: jest.fn().mockReturnValue('ok'),
  };
  const config = {
    get: (key: string) =>
      ({
        NODE_ENV: 'test',
        PALAZZO_ALLOWED_URLS: 'http://palazzo:3100',
      })[key],
  } as unknown as ConfigService;
  const machineClient = new PalazzoMachineClient(
    config,
    metrics,
    fetchImpl as unknown as typeof fetch,
  );
  const client = new PalazzoProgramClient({
    programId: PROGRAM,
    programType: 'radio',
    palazzoUrl: 'http://palazzo:3100',
    metrics,
    callbacks,
    machineClient,
    pollIntervalMs: 5,
  });
  return { client, metrics, callbacks };
}

function ignored(metrics: RadioMetricsService, reason: string): number {
  const line = metrics
    .render()
    .split('\n')
    .find((entry) =>
      entry.startsWith(
        `alcantara_palazzo_events_ignored_total{reason="${reason}"} `,
      ),
    );
  return Number(line?.split(' ').pop());
}

async function run(frames: ReturnType<typeof envelope>[]) {
  const fetchImpl = jest.fn().mockResolvedValue(sseResponse(frames.map(frame)));
  const created = createClient(fetchImpl);
  created.client.start();
  await new Promise((resolve) => setTimeout(resolve, 20));
  const internals = created.client as unknown as ClientInternals;
  const result = {
    ...created,
    fetchImpl,
    sequence: internals.lastSequence,
    boot: internals.currentBootId,
  };
  created.client.stop();
  return result;
}

describe('PalazzoProgramClient: replay.gap', () => {
  let warn: jest.SpyInstance;
  beforeEach(() => {
    warn = jest.spyOn(Logger.prototype, 'warn').mockImplementation();
  });
  afterEach(() => warn.mockRestore());

  const snapshot = () => envelope(5, 'snapshot', { state: idleState(5) });
  const gap = (
    data: unknown = { reason: 'cursor_not_in_replay', replayEvents: 512 },
  ) => envelope(5, 'replay.gap', data);

  it('records one gap, leaves the unknown-type counter alone and keeps the cursor at the snapshot', async () => {
    const started = envelope(6, 'track.started', {
      playbackRequestId: 'req-1',
      url: 'https://example.test/song.mp3',
    });
    const { metrics, callbacks, fetchImpl, sequence, boot } = await run([
      snapshot(),
      gap(),
      started,
    ]);

    expect(ignored(metrics, 'sequence-gap')).toBe(1);
    expect(ignored(metrics, 'unknown-type')).toBe(0);
    expect(ignored(metrics, 'duplicate')).toBe(0);
    expect(ignored(metrics, 'malformed')).toBe(0);
    // The cursor stayed at the snapshot, so the next event (6) is the very
    // next one, not a gap, and reaches the engine; the gap did not.
    expect(sequence).toBe(6);
    expect(boot).toBe('boot-1');
    expect(callbacks.onEvent).toHaveBeenCalledTimes(1);
    expect(callbacks.onEvent).toHaveBeenCalledWith(PROGRAM, started);
    expect(callbacks.onSnapshot).toHaveBeenCalledTimes(1);
    // Nothing was fetched for it: only the events connection.
    expect(
      fetchImpl.mock.calls.filter(
        ([url]) => !String(url).includes('/playback/events'),
      ),
    ).toHaveLength(0);
    expect(warn).toHaveBeenCalledTimes(1);
    expect(String(warn.mock.calls[0][0])).toContain(
      'replay window held 512 events',
    );
  });

  it('is logged once per gap and works without a replay count', async () => {
    const { metrics } = await run([
      snapshot(),
      gap({ reason: 'cursor_not_in_replay' }),
    ]);
    expect(ignored(metrics, 'sequence-gap')).toBe(1);
    expect(warn).toHaveBeenCalledTimes(1);
    expect(String(warn.mock.calls[0][0])).not.toContain('replay window held');
  });

  it('accepts a reason or fields it does not know', async () => {
    const { metrics } = await run([
      snapshot(),
      gap({ reason: 'something_new', replayEvents: 'many', extra: true }),
    ]);
    expect(ignored(metrics, 'sequence-gap')).toBe(1);
    expect(ignored(metrics, 'unknown-type')).toBe(0);
    expect(ignored(metrics, 'malformed')).toBe(0);
  });

  it('still rejects a replay.gap whose data is not an object as malformed', async () => {
    for (const data of ['text', 7, null, ['a']]) {
      const { metrics, callbacks } = await run([snapshot(), gap(data)]);
      expect(ignored(metrics, 'malformed')).toBe(1);
      expect(ignored(metrics, 'sequence-gap')).toBe(0);
      expect(ignored(metrics, 'unknown-type')).toBe(0);
      expect(callbacks.onEvent).not.toHaveBeenCalled();
    }
  });

  it('ignores a replay.gap before any snapshot was accepted, or from another boot', async () => {
    const before = await run([gap()]);
    expect(ignored(before.metrics, 'sequence-gap')).toBe(0);
    expect(ignored(before.metrics, 'superseded-boot')).toBe(1);
    const other = await run([
      snapshot(),
      envelope(5, 'replay.gap', { reason: 'cursor_not_in_replay' }, 'boot-2'),
    ]);
    expect(ignored(other.metrics, 'sequence-gap')).toBe(0);
    expect(ignored(other.metrics, 'superseded-boot')).toBe(1);
    expect(warn).not.toHaveBeenCalled();
  });

  it('does not change how another unknown type is handled', async () => {
    const { metrics } = await run([
      snapshot(),
      envelope(6, 'playout.something_new'),
    ]);
    expect(ignored(metrics, 'unknown-type')).toBe(1);
    expect(ignored(metrics, 'sequence-gap')).toBe(0);
  });
});

